+  static Heuristic value() {
+    return _value;
+  }
+private:
+  static Heuristic _value;
+};
+
+class ShenandoahModeFlag : public AllStatic {
+public:
+  enum class Mode {
+    GENERATIONAL, SATB, PASSIVE
+  };
+
+  static void initialize();
+  static Mode value() {
+    return _value;
+  }
+private:
+  static Mode _value;
+};
